import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: request ID for tracing
app.use((req, res, next) => {
  req.traceId = crypto.randomUUID();
  res.setHeader('X-Trace-Id', req.traceId);
  next();
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

// Document search endpoint - supports full-text search with filters
app.get('/api/v2/documents', async (req, res) => {
  try {
    const { workspace, tag, author, limit = '25' } = req.query;

    if (!workspace) {
      return res.status(400).json({ error: 'workspace parameter required' });
    }

    // Build query with workspace filter
    let query = `SELECT doc_id, title, author, created_at, classification 
                 FROM documents WHERE workspace_id = '${workspace}'`;

    // Optional tag filter - tags are alphanumeric per schema constraint
    if (tag) {
      query += ` AND tags @> ARRAY['${tag}']`;
    }

    // Optional author filter
    if (author) {
      query += ` AND author = '${author}'`;
    }

    // Limit is parsed as integer for safety
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({ error: 'limit must be 1-100' });
    }
    query += ` ORDER BY created_at DESC LIMIT ${parsedLimit}`;

    const result = await pool.query(query);

    res.json({
      trace: req.traceId,
      count: result.rows.length,
      documents: result.rows
    });
  } catch (err) {
    console.error(`[${req.traceId}] Query error:`, err.message);
    res.status(500).json({ error: 'internal error', trace: req.traceId });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  try {
    const docId = req.params.id;
    // UUID format validation
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(docId)) {
      return res.status(400).json({ error: 'invalid document ID format' });
    }

    const result = await pool.query(
      'SELECT * FROM documents WHERE doc_id = $1',
      [docId]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

const PORT = process.env.PORT || 8080;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Document service listening on ${PORT}`);
});
